(* [comment removed for export] *)
Record gvp : Type := mk_gvp { gv_D : Z; gv_N : Z; gv_w : Z; gv_h : Z; gv_wpl : Z }.
Definition gv_ok (p : gvp) : Prop :=
  0 < gv_w p <= 20000 /\ 0 < gv_h p <= 20000 /\ gv_wpl p = (gv_w p * 8 + 31) / 32 /\ gv_N p = 4 * (gv_wpl p * gv_h p)
  /\ 0 < gv_N p <= 0x4000000
  /\ 0 < gv_D p /\ gv_D p mod 16 = 0 /\ gv_D p + gv_N p <= 2^47 /\ (gv_D p + gv_N p <= 0x7fff7000 \/ 0x10007fff8000 <= gv_D p)
  /\ (gv_D p + gv_N p <= 0x10000 \/ 0x662000 <= gv_D p).
(* [comment removed for export] *)
Definition gv_e (ty e : Z) : Prop := 0 <= e <= 255 \/ (ty = L_SELECT_MIN /\ e = 100000) \/ (ty = L_SELECT_MAX /\ e = -1).

(* [comment removed for export] *)
Definition gv_j_exit (p : gvp) (L : Z) (ra sp gp tp s0 s1 a2 a3 a6 s2 s3 s4 s5 s7 s9 s10 s11 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
  : machine_state -> Prop :=
  fun ms' => exists (a0' t2' t3' : word) (e' : Z),
    ms' = MS (mkR ra sp gp tp (Z_to_bv 64 e') (Z_to_bv 64 (L + gv_w p)) t2' s0 s1 a0' (Z_to_bv 64 e') a2 a3 (Z_to_bv 64 (gv_w p)) (Z_to_bv 64 1) a6 (Z_to_bv 64 (gv_w p))
                  s2 s3 s4 s5 (Z_to_bv 64 1) s7 (Z_to_bv 64 2147450880) s9 s10 s11 t3' t4 t5 t6)
             F (Z_to_bv 64 0xa4600) fc None m (seg_rom asegs)
    /\ 0 <= e' <= 255.

Lemma land255 : forall v, 0 <= v < 256 -> Z.land v 255 = v.
