(* [comment removed for export] *)
Definition gv_i_exit (p : gvp) (ra sp gp tp s0 s1 s2 s3 s4 s5 s7 s10 s11 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
  : machine_state -> Prop :=
  fun ms' => exists (t1' t2' a0' t3' : word) (e' : Z),
    ms' = MS (mkR ra sp gp tp (Z_to_bv 64 e') t1' t2' s0 s1 a0' (Z_to_bv 64 e') (Z_to_bv 64 (gv_h p)) (Z_to_bv 64 (gv_h p)) (Z_to_bv 64 (gv_w p)) (Z_to_bv 64 1)
                  (Z_to_bv 64 (4 * gv_wpl p)) (Z_to_bv 64 (gv_w p))
                  s2 s3 s4 s5 (Z_to_bv 64 1) s7 (Z_to_bv 64 2147450880) (Z_to_bv 64 (gv_D p + 4 * gv_wpl p * gv_h p)) s10 s11 t3' t4 t5 t6)
             F (Z_to_bv 64 0xa47d8) fc None m (seg_rom asegs)
    /\ 0 <= e' <= 255.

(* [comment removed for export] *)
Lemma gv_i_loop : forall (n : nat) (p : gvp) (ty : Z) (i e : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a7 s2 s3 s4 s7 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = gv_h p - i -> 0 <= i -> (1 <= n)%nat -> gv_ok p -> (ty = L_SELECT_MIN \/ ty = L_SELECT_MAX) -> gv_e ty e ->
  wr_at asegs m (gv_D p) (gv_N p) -> acc asegs m (gv_D p) (gv_N p) -> mem_inv asegs m ->
  evt asegs (gv_i_exit p ra sp gp tp s0 s1 s2 s3 s4 (Z_to_bv 64 ty) s7 s10 s11 t4 t5 t6 F fc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 e) (Z_to_bv 64 (gv_h p)) (Z_to_bv 64 i) (Z_to_bv 64 (gv_w p)) (Z_to_bv 64 1)
